import pytest

from bedrock_protocol import v2168

# generated by gophertunnel b8bd735:
# &packet.Event{EntityRuntimeID: -5, UsePlayerID: true, Event: &protocol.MobKilledEvent{
#     KillerEntityUniqueID: 1, VictimEntityUniqueID: 2, KillerEntityType: 319, EntityDamageCause: 2,
#     VillagerTradeTier: -1, VillagerDisplayName: "trader"}}
MOB_KILLED = bytes.fromhex("090801040204fe04040106747261646572")

# generated by gophertunnel b8bd735:
# &packet.Event{EntityRuntimeID: 7, Event: &protocol.ItemUsedEvent{ItemID: 300, ItemAux: 5, UseMethod: 1,
#     UseCount: 2}}
ITEM_USED = bytes.fromhex("0e3e00142c01050000000100000002000000")

# generated by gophertunnel b8bd735:
# &packet.Event{EntityRuntimeID: 7, Event: &protocol.CauldronInteractEvent{BlockInteractionType: 9,
#     ItemID: 300}}
POI_CAULDRON_USED = bytes.fromhex("0e1e000a092c01")

GOLDENS = [
    pytest.param(
        v2168.LegacyTelemetryEventPacket(
            player_unique_id=-5,
            type=v2168.LegacyTelemetryEventPacket.Type.MOB_KILLED,
            use_player_id=True,
            event_data=v2168.LegacyTelemetryEventPacket.MobKilled(
                killer_entity_id=1,
                killed_mob_id=2,
                damage_child_type=v2168.ActorType.PLAYER,
                damage_source=2,
                trader_tier=-1,
                trader_name="trader",
            ),
        ),
        MOB_KILLED,
        id="mob-killed",
    ),
    pytest.param(
        v2168.LegacyTelemetryEventPacket(
            player_unique_id=7,
            type=v2168.LegacyTelemetryEventPacket.Type.ITEM_USED,
            use_player_id=False,
            event_data=v2168.LegacyTelemetryEventPacket.ItemUsed(item_id=300, item_aux=5, use_method=1, count=2),
        ),
        ITEM_USED,
        id="item-used",
    ),
    pytest.param(
        v2168.LegacyTelemetryEventPacket(
            player_unique_id=7,
            type=v2168.LegacyTelemetryEventPacket.Type.POI_CAULDRON_USED,
            use_player_id=False,
            event_data=v2168.LegacyTelemetryEventPacket.POICauldronUsed(
                interaction_type=v2168.MinecraftEventing.POIBlockInteractionType.COOKING, item_id=300
            ),
        ),
        POI_CAULDRON_USED,
        id="poi-cauldron-used",
    ),
]


@pytest.fixture
def honey_harvested():
    return v2168.LegacyTelemetryEventPacket(
        player_unique_id=7,
        type=v2168.LegacyTelemetryEventPacket.Type.HONEY_HARVESTED,
        use_player_id=False,
        event_data=v2168.LegacyTelemetryEventPacket.Empty(),
    )


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_legacy_telemetry_event_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_legacy_telemetry_event_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_the_payload_free_arm_writes_four_bytes(honey_harvested):
    assert len(bytes(honey_harvested)) == 4


def test_the_payload_free_arm_round_trips(honey_harvested):
    assert v2168.LegacyTelemetryEventPacket.from_bytes(bytes(honey_harvested)) == honey_harvested
